begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
set local timezone='UTC';
select no_plan();

select ok((select count(*)=5 and bool_and(prosecdef and 'search_path=""'=any(proconfig)) from pg_proc
 where pronamespace='public'::regnamespace and proname like 'community_ui_%'),'five interaction RPCs pin security-definer paths');
select ok((select bool_and(has_function_privilege('authenticated',oid,'EXECUTE') and not has_function_privilege('anon',oid,'EXECUTE')
 and not has_function_privilege('service_role',oid,'EXECUTE')) from pg_proc where pronamespace='public'::regnamespace and proname like 'community_ui_%'),
 'only authenticated sessions can invoke interaction RPCs');
select ok((select bool_and(not has_function_privilege(r,oid,'EXECUTE')) from pg_proc cross join unnest(array['anon','authenticated','service_role'])r
 where pronamespace='private'::regnamespace and proname like 'community_ui_%'),'interaction helpers are not client-callable');
select ok((select bool_and(not has_table_privilege(r,t,'INSERT,UPDATE,DELETE,TRUNCATE')) from unnest(array['anon','authenticated','service_role'])r
 cross join unnest(array['public.comments','public.post_likes','private.board_operations'])t),'no API role can bypass interaction RPC writes');
select is((select count(*) from private.community_policy),0::bigint,'interaction migration seeds no community policy');
select is((select count(*) from private.point_policy),0::bigint,'interaction migration seeds no reward policy');
select is((select count(*) from public.comments),0::bigint,'interaction migration creates no live comments');
select is((select count(*) from public.post_likes),0::bigint,'interaction migration creates no live likes');

create function pg_temp.id(n integer) returns uuid language sql immutable as $$select ('c5200000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
insert into auth.users(id,email,raw_user_meta_data) select pg_temp.id(n),'interaction-unit-'||n||'@example.invalid','{}'::jsonb from generate_series(1,8)n;
update public.profiles set call_name='가상댓글팬',onboarding_completed_at=clock_timestamp() where id::text like 'c5200000-%';
update public.profiles set role='admin' where id=pg_temp.id(3);
update public.profiles set onboarding_completed_at=null where id=pg_temp.id(4);
update public.profiles set is_restricted=true where id=pg_temp.id(5);
update public.profiles set is_restricted=true,restricted_until=clock_timestamp()-interval '1 second' where id=pg_temp.id(6);
update public.profiles set role='artist',onboarding_completed_at=null,call_name=null where id=pg_temp.id(7);
insert into public.artists(id,slug,name,grade,status) values
 (pg_temp.id(101),'interaction-unit','Fictional interaction artist','B','active'),
 (pg_temp.id(102),'interaction-paused','Fictional paused artist','B','paused'),
 (pg_temp.id(103),'interaction-other','Fictional other artist','B','active');
insert into public.posts(id,artist_id,user_id,request_id,title,body) values
 (pg_temp.id(201),pg_temp.id(101),pg_temp.id(1),pg_temp.id(901),'Fictional post','Fictional body'),
 (pg_temp.id(202),pg_temp.id(101),pg_temp.id(2),pg_temp.id(902),'Other fictional post','Other fictional body'),
 (pg_temp.id(203),pg_temp.id(103),pg_temp.id(1),pg_temp.id(903),'Other board post','Other board body');
create temporary table interaction_context(key text primary key,data jsonb);
grant all on interaction_context to authenticated;
create function pg_temp.read_comments(p_limit integer default 21,p_after_created_at timestamptz default null,p_after_id uuid default null)
returns jsonb language sql as $$select public.community_ui_interactions('interaction-unit',pg_temp.id(201),p_limit,p_after_created_at,p_after_id)$$;
create function pg_temp.create_comment(p_id integer default 301,p_op integer default 401,p_body text default 'Fictional comment',p_post integer default 201)
returns jsonb language sql as $$select public.community_ui_create_comment('interaction-unit',pg_temp.id(p_op),pg_temp.id(p_post),pg_temp.id(p_id),p_body)$$;

set local role anon;
select throws_ok($$select pg_temp.read_comments()$$,'42501',null,'anonymous cannot read interactions');
select throws_ok($$select pg_temp.create_comment()$$,'42501',null,'anonymous cannot create comments');
select throws_ok($$select public.community_ui_update_comment('interaction-unit',pg_temp.id(501),pg_temp.id(201),pg_temp.id(301),1,'Changed')$$,'42501',null,'anonymous cannot update comments');
select throws_ok($$select public.community_ui_delete_comment('interaction-unit',pg_temp.id(601),pg_temp.id(201),pg_temp.id(301),1,true)$$,'42501',null,'anonymous cannot delete comments');
select throws_ok($$select public.community_ui_set_like('interaction-unit',pg_temp.id(701),pg_temp.id(201),true)$$,'42501',null,'anonymous cannot like posts');
reset role;
set local role service_role;
select throws_ok($$select pg_temp.read_comments()$$,'42501',null,'service role cannot impersonate interaction reader');
select throws_ok($$select pg_temp.create_comment()$$,'42501',null,'service role cannot create a user comment');
select throws_ok($$select public.community_ui_set_like('interaction-unit',pg_temp.id(701),pg_temp.id(201),true)$$,'42501',null,'service role cannot like as a user');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub',pg_temp.id(1)::text,true);
select throws_ok($$select pg_temp.read_comments()$$,'55000','COMMUNITY_POLICY_REQUIRED','read fails closed without policy');
select throws_ok($$select pg_temp.create_comment()$$,'55000','COMMUNITY_POLICY_REQUIRED','create fails closed without policy');
select throws_ok($$select public.community_ui_set_like('interaction-unit',pg_temp.id(701),pg_temp.id(201),true)$$,'55000','COMMUNITY_POLICY_REQUIRED','like fails closed without policy');
reset role;
insert into private.community_policy(version,max_title_length,max_body_length,max_comment_length,max_reason_length,max_images,max_image_bytes,max_image_long_edge,auto_hide_report_count,rate_window_seconds,max_contributions_per_window,max_reports_per_window,forbidden_terms,forbidden_patterns)
values('fictional-interaction-tests',100,1000,100,100,3,10000,2048,2,60,100,100,array['blockedword'],array['[0-9]{3}-[0-9]{4}-[0-9]{4}']);
set local role authenticated;
select is(pg_temp.read_comments()->'comments','[]'::jsonb,'empty comment list is actual empty state');
select is(pg_temp.read_comments()->>'actor_id',pg_temp.id(1)::text,'read is bound to current actor');
select is(pg_temp.read_comments()->>'post_id',pg_temp.id(201)::text,'read is bound to requested post');
select is(pg_temp.read_comments()->'policy','{"max_comment_length":100}'::jsonb,'read exposes only the approved comment limit');
select is(pg_temp.read_comments()->'next_cursor','null'::jsonb,'empty list has no fabricated next cursor');
select is((pg_temp.read_comments()->>'liked')::boolean,false,'absence of like is false');
select is((pg_temp.read_comments()->>'comment_count')::integer,0,'empty visible count is zero');
select is((pg_temp.read_comments()->>'like_count')::integer,0,'empty like count is zero');
select throws_ok($$select pg_temp.read_comments(0)$$,'22023','BOARD_INVALID_INPUT','zero limit rejected');
select throws_ok($$select pg_temp.read_comments(101)$$,'22023','BOARD_INVALID_INPUT','unbounded limit rejected');
select throws_ok($$select pg_temp.read_comments(null)$$,'22023','BOARD_INVALID_INPUT','null limit rejected');
select throws_ok($$select pg_temp.read_comments(1,now(),null)$$,'22023','BOARD_INVALID_INPUT','timestamp-only cursor rejected');
select throws_ok($$select pg_temp.read_comments(1,null,pg_temp.id(301))$$,'22023','BOARD_INVALID_INPUT','id-only cursor rejected');
select throws_ok($$select pg_temp.read_comments(1,'infinity',pg_temp.id(301))$$,'22023','BOARD_INVALID_INPUT','nonfinite cursor rejected');
select throws_ok($$select public.community_ui_interactions('interaction-unit',null)$$,'22023','BOARD_INVALID_INPUT','null post identity rejected');
select throws_ok($$select public.community_ui_interactions('interaction-paused',pg_temp.id(201))$$,'42501','COMMUNITY_BOARD_UNAVAILABLE','paused board denied');
select throws_ok($$select public.community_ui_interactions('missing',pg_temp.id(201))$$,'42501','COMMUNITY_BOARD_UNAVAILABLE','unknown board denied');
select throws_ok($$select public.community_ui_interactions('interaction-other',pg_temp.id(201))$$,'42501','COMMUNITY_TARGET_UNAVAILABLE','read cannot cross route board');
select throws_ok($$select pg_temp.create_comment(p_post=>203)$$,'42501','COMMUNITY_TARGET_UNAVAILABLE','create cannot cross route board');
select throws_ok($$select pg_temp.create_comment(p_op=>null)$$,'22023','BOARD_INVALID_INPUT','create requires operation identity');
select throws_ok($$select pg_temp.create_comment(p_id=>null)$$,'22023','BOARD_INVALID_INPUT','create requires comment identity');
select throws_ok($$select pg_temp.create_comment(p_body=>null)$$,'23514','COMMUNITY_CONTENT_INVALID','null body rejected');
select throws_ok($$select pg_temp.create_comment(p_body=>'  ')$$,'23514','COMMUNITY_CONTENT_INVALID','blank body rejected');
select throws_ok($$select pg_temp.create_comment(p_body=>repeat('a',101))$$,'23514','COMMUNITY_CONTENT_INVALID','approved length bound enforced');
select throws_ok($$select pg_temp.create_comment(p_body=>'BLOCKEDWORD')$$,'23514','COMMUNITY_CONTENT_BLOCKED','configured forbidden term enforced');
select throws_ok($$select pg_temp.create_comment(p_body=>'010-1234-5678')$$,'23514','COMMUNITY_CONTENT_BLOCKED','configured sensitive pattern enforced');
select throws_ok($$select pg_temp.create_comment(p_body=>E'hello\x01')$$,'23514','COMMUNITY_CONTENT_INVALID','control character body rejected');
insert into interaction_context values('create',pg_temp.create_comment());
select is(pg_temp.create_comment(),(select data from interaction_context where key='create'),'exact create retry returns original receipt');
select is((select data from interaction_context where key='create'),jsonb_build_object('id',pg_temp.id(301),'post_id',pg_temp.id(201),'revision',1),'create receipt exposes minimal identifiers and revision');
select throws_ok($$select pg_temp.create_comment(p_body=>'Changed payload')$$,'23505','BOARD_OPERATION_CONFLICT','create retry cannot change body');
select throws_ok($$select pg_temp.create_comment(p_op=>405)$$,'23505','BOARD_OPERATION_CONFLICT','new operation cannot reuse comment identity');
select throws_ok($$select pg_temp.create_comment(p_id=>305)$$,'23505','BOARD_OPERATION_CONFLICT','same operation cannot change comment identity');
select throws_ok($$select public.community_ui_set_like('interaction-unit',pg_temp.id(401),pg_temp.id(201),true)$$,'23505','BOARD_OPERATION_CONFLICT','operation namespace cannot cross create and like actions');
select is((pg_temp.read_comments()->>'comment_count')::integer,1,'exact retry increments comment counter once');
select is(pg_temp.read_comments()->'comments'->0->>'body','Fictional comment','list reads persisted body');
select is(pg_temp.read_comments()->'comments'->0->'author','{"call_name":"가상댓글팬"}'::jsonb,'author DTO exposes only calling name');
select ok((pg_temp.read_comments()->'comments'->0->>'is_owner')::boolean,'owner affordance follows DB identity');
select ok(not (pg_temp.read_comments()->'comments'->0) ?| array['user_id','request_id','is_hidden','report_count','deleted_at'],'comment DTO omits internal identity and moderation data');
select lives_ok($$select pg_temp.create_comment(302,402,'Second fictional comment')$$,'second comment created');
select set_config('request.jwt.claim.sub',pg_temp.id(2)::text,true);
select lives_ok($$select pg_temp.create_comment(303,403,'Third fictional comment')$$,'other eligible fan may comment without subscription');
select ok(not (pg_temp.read_comments()->'comments'->0->>'is_owner')::boolean,'other actor sees no owner affordance');
select throws_ok($$select public.community_ui_update_comment('interaction-unit',pg_temp.id(501),pg_temp.id(201),pg_temp.id(301),1,'Other edit')$$,'42501','COMMUNITY_TARGET_UNAVAILABLE','other actor cannot edit comment');
select throws_ok($$select public.community_ui_delete_comment('interaction-unit',pg_temp.id(601),pg_temp.id(201),pg_temp.id(301),1,true)$$,'42501','COMMUNITY_TARGET_UNAVAILABLE','other actor cannot delete comment');
select set_config('request.jwt.claim.sub',pg_temp.id(1)::text,true);
insert into interaction_context values('first',pg_temp.read_comments(1));
select is((select data->'comments'->0->>'id' from interaction_context where key='first'),pg_temp.id(301)::text,'oldest-first order uses UUID to break equal timestamp ties');
select is(jsonb_array_length(pg_temp.read_comments(1)->'comments'),1,'bounded page includes one visible comment');
select is(pg_temp.read_comments(1,((select data->'next_cursor'->>'created_at' from interaction_context where key='first'))::timestamptz,
 ((select data->'next_cursor'->>'id' from interaction_context where key='first'))::uuid)->'comments'->0->>'id',pg_temp.id(302)::text,'cursor advances without duplicate');
select is(pg_temp.read_comments(100)->'next_cursor','null'::jsonb,'last page ends cursor');
select is((pg_temp.read_comments()->>'comment_count')::integer,3,'full counter remains independent of page size');
reset role;
select is((select count(*) from private.point_ledger),0::bigint,'no configured point policy means no fabricated awards');
select is((select contributions from private.community_rate_limits where user_id=pg_temp.id(1)),2,'create retries charge contribution rate once');
insert into private.point_policy(version,attendance_amount,post_amount,comment_amount,post_daily_cap,comment_daily_cap,deleted_content_treatment)
values('fictional-interaction-rewards',1,2,3,null,null,'retain');
set local role authenticated;
select lives_ok($$select pg_temp.create_comment(304,404,'Rewarded fictional comment')$$,'configured existing reward trigger accepts UI create');
select lives_ok($$select pg_temp.create_comment(304,404,'Rewarded fictional comment')$$,'rewarded create exact replay accepted');
select throws_ok($$select public.community_ui_update_comment('interaction-unit',pg_temp.id(501),pg_temp.id(202),pg_temp.id(301),1,'Changed')$$,'42501','COMMUNITY_TARGET_UNAVAILABLE','update cannot move a comment to another post');
select throws_ok($$select public.community_ui_update_comment('interaction-unit',pg_temp.id(501),pg_temp.id(201),pg_temp.id(301),0,'Changed')$$,'22023','BOARD_INVALID_INPUT','zero edit revision rejected');
select throws_ok($$select public.community_ui_update_comment('interaction-unit',pg_temp.id(501),pg_temp.id(201),pg_temp.id(301),9007199254740991,'Changed')$$,'22023','BOARD_INVALID_INPUT','overflowing edit revision rejected');
select throws_ok($$select public.community_ui_update_comment('interaction-unit',pg_temp.id(501),pg_temp.id(201),pg_temp.id(301),1,'blockedword')$$,'23514','COMMUNITY_CONTENT_BLOCKED','edit validates existing content policy');
insert into interaction_context values('update',public.community_ui_update_comment('interaction-unit',pg_temp.id(501),pg_temp.id(201),pg_temp.id(301),1,'Edited fictional comment'));
select is((select data->>'revision' from interaction_context where key='update'),'2','edit advances CAS revision');
select is(public.community_ui_update_comment('interaction-unit',pg_temp.id(501),pg_temp.id(201),pg_temp.id(301),1,'Edited fictional comment'),
 (select data from interaction_context where key='update'),'exact edit retry returns immutable receipt');
select throws_ok($$select public.community_ui_update_comment('interaction-unit',pg_temp.id(501),pg_temp.id(201),pg_temp.id(301),1,'Different body')$$,'23505','BOARD_OPERATION_CONFLICT','edit retry cannot change body');
select throws_ok($$select public.community_ui_update_comment('interaction-unit',pg_temp.id(503),pg_temp.id(201),pg_temp.id(301),1,'Stale edit')$$,'40001','BOARD_REVISION_CONFLICT','stale edit fails instead of overwriting');
select is(public.community_ui_update_comment('interaction-unit',pg_temp.id(502),pg_temp.id(201),pg_temp.id(301),2,'Edited fictional comment')->>'revision','2','unchanged body creates receipt without false revision');
select lives_ok($$select public.community_update_comment(pg_temp.id(301),'Legacy edit')$$,'legacy comment edit remains supported');
select throws_ok($$select public.community_ui_update_comment('interaction-unit',pg_temp.id(504),pg_temp.id(201),pg_temp.id(301),2,'Stale UI edit')$$,'40001','BOARD_REVISION_CONFLICT','legacy edit invalidates stale UI revision');
select is(public.community_ui_update_comment('interaction-unit',pg_temp.id(501),pg_temp.id(201),pg_temp.id(301),1,'Edited fictional comment')->>'revision','2','old replay returns original receipt without overwriting newer legacy edit');
select is(pg_temp.read_comments()->'comments'->0->>'body','Legacy edit','immutable edit replay leaves newer body intact');
select is((pg_temp.read_comments()->>'comment_count')::integer,4,'edit never changes visible count');
select throws_ok($$select public.community_ui_delete_comment('interaction-unit',pg_temp.id(601),pg_temp.id(201),pg_temp.id(304),1,false)$$,'22023','BOARD_CONFIRMATION_REQUIRED','delete requires explicit confirmation');
select throws_ok($$select public.community_ui_delete_comment('interaction-unit',pg_temp.id(601),pg_temp.id(201),pg_temp.id(304),0,true)$$,'22023','BOARD_INVALID_INPUT','delete requires valid revision');
select throws_ok($$select public.community_ui_delete_comment('interaction-unit',pg_temp.id(601),pg_temp.id(201),pg_temp.id(301),1,true)$$,'40001','BOARD_REVISION_CONFLICT','stale delete fails');
insert into interaction_context values('delete',public.community_ui_delete_comment('interaction-unit',pg_temp.id(601),pg_temp.id(201),pg_temp.id(304),1,true));
select is(public.community_ui_delete_comment('interaction-unit',pg_temp.id(601),pg_temp.id(201),pg_temp.id(304),1,true),
 (select data from interaction_context where key='delete'),'exact deletion retry recovers tombstone receipt');
select throws_ok($$select public.community_ui_delete_comment('interaction-unit',pg_temp.id(602),pg_temp.id(201),pg_temp.id(304),1,true)$$,'42501','COMMUNITY_TARGET_UNAVAILABLE','new deletion operation cannot reuse tombstone');
select throws_ok($$select pg_temp.create_comment(304,404,'Rewarded fictional comment')$$,'42501','COMMUNITY_TARGET_UNAVAILABLE','create replay cannot access deleted comment');
select is((pg_temp.read_comments()->>'comment_count')::integer,3,'delete decrements visible count once');
select is(jsonb_array_length(pg_temp.read_comments()->'comments'),3,'deleted comment is omitted without leaking body or tombstone');
reset role;
select ok((select deleted_at is not null and is_hidden and revision=2 from public.comments where id=pg_temp.id(304)),'delete is terminal soft deletion with advanced revision');
select is((select count(*) from public.community_moderation_log where target_id=pg_temp.id(304) and action='delete'),1::bigint,'delete retry writes one existing audit record');
select is((select count(*) from private.point_ledger where comment_id=pg_temp.id(304)),1::bigint,'creation retry and deletion retain exactly one existing reward');
select is((select amount from private.point_ledger where comment_id=pg_temp.id(304)),3::bigint,'existing explicit reward amount is preserved');
set local role authenticated;
select set_config('request.jwt.claim.sub',pg_temp.id(3)::text,true);
select throws_ok($$select public.community_ui_delete_comment('interaction-unit',pg_temp.id(603),pg_temp.id(201),pg_temp.id(301),3,true)$$,'42501','COMMUNITY_TARGET_UNAVAILABLE','UI owner delete grants no administrator moderation shortcut');
select set_config('request.jwt.claim.sub',pg_temp.id(1)::text,true);
insert into interaction_context values('like',public.community_ui_set_like('interaction-unit',pg_temp.id(701),pg_temp.id(201),true));
select is((pg_temp.read_comments()->>'like_count')::integer,1,'desired like inserts once and increments counter');
select is((pg_temp.read_comments()->>'liked')::boolean,true,'read reports current actor liked');
select is(public.community_ui_set_like('interaction-unit',pg_temp.id(701),pg_temp.id(201),true),(select data from interaction_context where key='like'),'exact like replay returns immutable receipt');
select is((pg_temp.read_comments()->>'like_count')::integer,1,'duplicate like does not increment twice');
select lives_ok($$select public.community_ui_set_like('interaction-unit',pg_temp.id(702),pg_temp.id(201),false)$$,'unlike records desired false state');
select is((pg_temp.read_comments()->>'like_count')::integer,0,'unlike decrements counter once');
select is(public.community_ui_set_like('interaction-unit',pg_temp.id(701),pg_temp.id(201),true),(select data from interaction_context where key='like'),'old like receipt is recoverable after newer unlike');
select is((pg_temp.read_comments()->>'liked')::boolean,false,'old replay never reapplies stale true over newer false');
insert into interaction_context values('post-revision',to_jsonb((select revision from public.posts where id=pg_temp.id(201))));
select lives_ok($$select public.community_ui_set_like('interaction-unit',pg_temp.id(703),pg_temp.id(201),false)$$,'already-false desired state records a no-op receipt');
select is(to_jsonb((select revision from public.posts where id=pg_temp.id(201))),(select data from interaction_context where key='post-revision'),'no-op desired like leaves post revision unchanged');
select throws_ok($$select public.community_ui_set_like('interaction-unit',pg_temp.id(703),pg_temp.id(201),true)$$,'23505','BOARD_OPERATION_CONFLICT','same like operation cannot flip payload');
select throws_ok($$select public.community_ui_set_like('interaction-unit',pg_temp.id(704),pg_temp.id(201),null)$$,'22023','BOARD_INVALID_INPUT','null desired state rejected');
select throws_ok($$select public.community_ui_set_like('interaction-unit',null,pg_temp.id(201),true)$$,'22023','BOARD_INVALID_INPUT','like requires immutable operation identity');
select set_config('request.jwt.claim.sub',pg_temp.id(2)::text,true);
select lives_ok($$select public.community_ui_set_like('interaction-unit',pg_temp.id(701),pg_temp.id(201),true)$$,'same UUID on a different actor remains separately bound');
select set_config('request.jwt.claim.sub',pg_temp.id(1)::text,true);
select is((pg_temp.read_comments()->>'liked')::boolean,false,'another actor like does not set current actor liked');
select is((pg_temp.read_comments()->>'like_count')::integer,1,'another actor contributes to shared count');
select lives_ok($$select public.community_ui_set_like('interaction-unit',pg_temp.id(704),pg_temp.id(201),true)$$,'second distinct actor like is accepted');
select is((pg_temp.read_comments()->>'like_count')::integer,2,'distinct likes count independently');
select set_config('request.jwt.claim.sub',pg_temp.id(2)::text,true);
select lives_ok($$select public.community_set_like(pg_temp.id(201),false)$$,'legacy unlike remains interoperable');
select set_config('request.jwt.claim.sub',pg_temp.id(1)::text,true);
select lives_ok($$select public.community_ui_set_like('interaction-unit',pg_temp.id(705),pg_temp.id(201),false)$$,'UI unlike interoperates with legacy counter');
select is((pg_temp.read_comments()->>'like_count')::integer,0,'mixed APIs leave counter equal to actual likes');
reset role;
select is((select like_count from public.posts where id=pg_temp.id(201)),(select count(*)::integer from public.post_likes where post_id=pg_temp.id(201)),'persisted like counter equals actual rows');
select throws_ok($$update private.board_operations set response='{}' where request->>'action'='like'$$,'55000','BOARD_OPERATION_IMMUTABLE','interaction receipts retain existing immutable trigger');

-- Every retry rechecks current policy, actor and parent before acknowledging a
-- historical receipt. A receipt is never fresh access to hidden content.
create temporary table saved_interaction_policy as table private.community_policy;
delete from private.community_policy;
set local role authenticated;
select throws_ok($$select pg_temp.read_comments()$$,'55000','COMMUNITY_POLICY_REQUIRED','policy removal revokes reads');
select throws_ok($$select pg_temp.create_comment()$$,'55000','COMMUNITY_POLICY_REQUIRED','create receipt still requires current policy');
select throws_ok($$select public.community_ui_update_comment('interaction-unit',pg_temp.id(501),pg_temp.id(201),pg_temp.id(301),1,'Edited fictional comment')$$,'55000','COMMUNITY_POLICY_REQUIRED','edit receipt still requires current policy');
select throws_ok($$select public.community_ui_delete_comment('interaction-unit',pg_temp.id(601),pg_temp.id(201),pg_temp.id(304),1,true)$$,'55000','COMMUNITY_POLICY_REQUIRED','delete receipt still requires current policy');
select throws_ok($$select public.community_ui_set_like('interaction-unit',pg_temp.id(701),pg_temp.id(201),true)$$,'55000','COMMUNITY_POLICY_REQUIRED','like receipt still requires current policy');
reset role;
insert into private.community_policy select * from saved_interaction_policy;
update public.profiles set is_restricted=true where id=pg_temp.id(1);
set local role authenticated;
select throws_ok($$select pg_temp.read_comments()$$,'42501','COMMUNITY_FORBIDDEN','new restriction revokes visible interactions');
select throws_ok($$select pg_temp.create_comment()$$,'42501','COMMUNITY_FORBIDDEN','restriction revokes create receipt');
